def maxProduct(s: str) -> int:
    n = len(s)
    palindromes = {}
    for mask in range(1, 1 << n):
        subseq = [s[i] for i in range(n) if (mask & (1 << i))]
        if subseq == subseq[::-1]:
            palindromes[mask] = len(subseq)
    ans = 0
    p_items = list(palindromes.items())
    for i in range(len(p_items)):
        m1, l1 = p_items[i]
        for j in range(i + 1, len(p_items)):
            m2, l2 = p_items[j]
            if (m1 & m2) == 0:
                prod = l1 * l2
                if prod > ans:
                    ans = prod
    return ans

